step.script:
env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "$TARGET_CITY" | tr "[:upper:]" "[:lower:]")"; docker run --rm -v /home/ubuntu/data_storage:/src_data:ro -v /home/ubuntu/work/frontend_build/test_frontend:/repo alpine:3.20 sh -lc " set -eu; SRC_DIR=\"\"; for d in /src_data/*; do
  [ -d \"\$d\" ] || continue;
  if [ \"\$(basename \"\$d\" | tr \"[:upper:]\" \"[:lower:]\")\" = \"$CITY_SLUG\" ]; then
    SRC_DIR=\"\$d\";
    break;
  fi;
done; if [ -z \"\$SRC_DIR\" ]; then
  echo \"City data folder not found in /home/ubuntu/data_storage for $TARGET_CITY\";
  exit 1;
fi; SRC_FILE=\"\$SRC_DIR/00_master/master_events.json\"; DEST_FILE=\"/repo/data/$CITY_SLUG/master_events.json\"; [ -f \"\$SRC_FILE\" ] || { echo \"Missing source file: \$SRC_FILE\"; exit 1; }; mkdir -p \"\$(dirname \"\$DEST_FILE\")\"; cp \"\$SRC_FILE\" \"\$DEST_FILE\"; echo \"Snapshot copied to \$DEST_FILE\" "'

env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "$TARGET_CITY" | tr "[:upper:]" "[:lower:]")"; SNAPSHOT_PATH="data/$CITY_SLUG/master_events.json"; docker run --rm --entrypoint sh -v /home/ubuntu/work/frontend_build/test_frontend:/repo -v /home/ubuntu/.ssh:/root/.ssh:ro -w /repo alpine/git:latest -lc " set -eu; git config --global --add safe.directory /repo; git checkout main; git pull origin main; git add \"$SNAPSHOT_PATH\"; if git diff --cached --quiet -- \"$SNAPSHOT_PATH\"; then
  echo \"No snapshot changes to commit for $SNAPSHOT_PATH\";
  exit 0;
fi; COMMIT_MSG=\"chore(snapshot): update master_events for $CITY_SLUG \$(date -u +%Y-%m-%dT%H:%M:%SZ)\"; git -c user.name=\"Dagu Snapshot Bot\" -c user.email=\"dagu-snapshot@example.com\" commit -m \"\$COMMIT_MSG\" -- \"$SNAPSHOT_PATH\"; git push origin main "'

env HOME=/tmp bash -lc 'set -eu; IMAGE="infra_scripts-test_frontend_build:latest"; if ! docker image inspect "$IMAGE" >/dev/null 2>&1; then
  echo "Missing image: $IMAGE";
  echo "Build it first with: docker compose --profile build build test_frontend_build";
  exit 1;
fi; EXTRA_ARGS=""; if [ "${SKIP_DOWNLOAD_IMAGES}" = "1" ]; then
  EXTRA_ARGS="--no-download-images";
fi; docker run --rm --entrypoint sh -e ORBITA_CITY="$TARGET_CITY" -v /home/ubuntu/work/frontend_build/test_frontend:/app -v infra_scripts_test_frontend_node_modules:/app/node_modules -v /home/ubuntu/work/frontend_build/test_frontend/dist:/app/dist -v /home/ubuntu/data_storage:/home/ubuntu/data_storage "$IMAGE" scripts/docker_static_entrypoint.sh --city "$TARGET_CITY" --out "dist" --base-url "$BASE_URL" $EXTRA_ARGS'

env HOME=/tmp bash -lc 'set -eu; if [ "${CLEAN_UP}" != "1" ]; then
  echo "CLEAN_UP != 1, skipping cleanup";
  exit 0;
fi; CITY_SLUG="$(printf "%s" "$TARGET_CITY" | tr "[:upper:]" "[:lower:]")"; docker run --rm --entrypoint sh -e BUNNY_STORAGE_ZONE="$BUNNY_STORAGE_ZONE" -e BUNNY_STORAGE_API_KEY="$BUNNY_STORAGE_API_KEY" -e CITY_SLUG="$CITY_SLUG" -v /home/ubuntu/work/frontend_build/test_frontend/dist:/app/dist infra_scripts-test_frontend:latest -c "set +e; cd /app/dist/$CITY_SLUG; lftp -u \"$BUNNY_STORAGE_ZONE,$BUNNY_STORAGE_API_KEY\" storage.bunnycdn.com -e \"cd $CITY_SLUG; mirror -R --delete --parallel=10 . .; bye\" || true"'

env HOME=/tmp bash -lc 'set -eu; if [ -z "${BUNNY_PULL_ZONE_ID}" ]; then
  echo "BUNNY_PULL_ZONE_ID is not set, skipping cache purge";
  exit 0;
fi; echo "Purging BunnyCDN cache for pull zone ${BUNNY_PULL_ZONE_ID}..."; HTTP_STATUS=$(docker run --rm curlimages/curl:latest -s -o /dev/null -w "%{http_code}" -X POST "https://api.bunny.net/pullzone/${BUNNY_PULL_ZONE_ID}/purgeCache" -H "AccessKey: ${BUNNY_ACCOUNT_API_KEY}" -H "Content-Type: application/json"); echo "HTTP status: $HTTP_STATUS"; if [ "$HTTP_STATUS" != "204" ]; then
  echo "Cache purge failed with HTTP status $HTTP_STATUS";
  exit 1;
fi; echo "Cache purged successfully"'

